import shlex
import subprocess
import sys


def build_command(src: str, dst: str) -> str:
    """Assemble the ffmpeg command line for a 480p web preview."""
    return (
        f"ffmpeg -y -i {shlex.quote(src)} -vf scale=-2:480 "
        f"-c:v libx264 -preset veryfast -movflags +faststart {shlex.quote(dst)}"
    )


def transcode(src: str, dst: str = "preview.mp4") -> int:
    """Render a 480p preview of ``src`` and return ffmpeg's exit code."""
    command = build_command(src, dst)
    return subprocess.run(command, shell=True).returncode
